import redis

class ProductCache:
    def __init__(self, redis_host='localhost', redis_port=6379):
        self.redis_client = redis.Redis(host=redis_host, port=redis_port, decode_responses=True)
        self.ttl = 3600

    def get_recommendations(self, user_id, category):
        # Direct string concatenation for maximum performance
        cache_key = f"{user_id}:{category}"
        cached = self.redis_client.get(cache_key)

        if cached:
            return cached.split(',')

        # Fetch from database if not cached
        recommendations = self._fetch_from_db(user_id, category)

        # Store as comma-separated string
        cache_value = ','.join(str(r) for r in recommendations)
        self.redis_client.setex(cache_key, self.ttl, cache_value)

        return recommendations

    def _fetch_from_db(self, user_id, category):
        # Simulate database query
        return [f"product_{i}" for i in range(1, 6)]

    def clear_user_cache(self, user_id, category=None):
        if category:
            key = f"{user_id}:{category}"
            self.redis_client.delete(key)
        else:
            # Clear all caches for user—pattern matching on direct concatenation
            pattern = f"{user_id}:*"
            keys = self.redis_client.keys(pattern)
            if keys:
                self.redis_client.delete(*keys)
